class CreateFoundationSkDocument extends CreateRecord { protected static string $resource=FoundationSkDocumentResource::class; protected function handleRecordCreation(array $data): Model { $file=$data['file']??null;unset($data['file']);abort_unless($file instanceof \Illuminate\Http\UploadedFile,422,'File SK wajib diunggah.');$user=User::findOrFail($data['user_id']);$templateId=filled($data['sk_template_id']??null)?(int)$data['sk_template_id']:null;return app(FoundationSkDocumentService::class)->store($user,(int)$data['tahun_sk'],$templateId,$file,auth()->user()); } }
